#!/usr/bin/env python3
from pathlib import Path
import argparse,hashlib,json
from VERIFY_SEMANTICS import validate,VerificationError
p=argparse.ArgumentParser(); p.add_argument('--deep',action='store_true'); a=p.parse_args()
root=Path(__file__).resolve().parent
manifest=root/'MANIFEST.sha256'
if not manifest.is_file(): raise SystemExit('FAIL missing manifest')
rows=[]
for line in manifest.read_text().splitlines():
 if not line.strip(): continue
 d,rel=line.split('  ',1); rows.append((d,rel))
for d,rel in rows:
 f=root/rel
 if not f.is_file(): raise SystemExit(f'FAIL missing {rel}')
 if hashlib.sha256(f.read_bytes()).hexdigest()!=d: raise SystemExit(f'FAIL hash mismatch {rel}')
if a.deep:
 for f in root.rglob('*.json'): json.loads(f.read_text())
 try: info=validate(root)
 except VerificationError as e: raise SystemExit(f'FAIL semantic: {e}')
print(f'PASS_TRACE_ESCAPE_STORY_FINAL_R55_TARKA {len(rows)} A1={info["a1_sha256"]}')

