from pathlib import Path
import json,re,hashlib
class VerificationError(Exception): pass
ALLOWED_TEMPLATES={
 '{{E03_Q1_PRIOR_ACCEPTED_COUNT}}','{{E03_Q2_PRIOR_ACCEPTED_COUNT}}','{{E03_Q2_CURRENT_ACCEPTED_COUNT}}'}
EXPECTED_A1='c665ad8150efb170452d177aba9cfa63be79ee3b9774dc15d1c2ecff850cfca5'
def fail(msg): raise VerificationError(msg)
def validate(root:Path):
 a1=(root/'FULL_TEXT/02_A1_OPENING_AND_AUTHORIZATION_FULL.md').read_bytes()
 b=b'<!-- BEGIN EXACT A1.1-A1.5 CARRY-FORWARD -->\n'; e=b'<!-- END EXACT A1.1-A1.5 CARRY-FORWARD -->'
 if b not in a1 or e not in a1: fail('missing A1 markers')
 exact=a1.split(b,1)[1].split(e,1)[0]
 if hashlib.sha256(exact).hexdigest()!=EXPECTED_A1: fail('A1 exact hash mismatch')
 text=a1.decode('utf-8')
 if 'A1.1 through A1.5 are approved and unchanged' in text: fail('A1 approval shortcut remains')
 if 'mathematically\nprecise haystack' not in text: fail('missing mathematically precise haystack canon')
 if 'ROOK:\n“Sounds complicated.”\n\nARTHUR:\n“It is.”\n\nARTHUR:\n“Fortunately,' not in text: fail('incorrect haystack-to-Nansen transition')
 if re.search(r'hieroglyph', text, re.I): fail('hieroglyphs analogy reintroduced into active A1')
 title=(root/'PUBLIC_TITLE/16_TARKA_PUBLIC_TITLE_LAUNCH_CREDITS_AND_DOCUMENTATION_CONTRACT.md').read_text()
 if '\nACCESSIBILITY\n' in title: fail('launch Accessibility control remains')
 active=[]
 for p in root.rglob('*'):
  if not p.is_file() or p.suffix not in {'.md','.txt','.json'}: continue
  if 'MAIN_INPUT' in p.parts or p.name=='13_SUPERSEDED_DO_NOT_REVIVE.md': continue
  active.append((p,p.read_text(encoding='utf-8')))
 forbidden=[
  'TITLE_ACCESSIBILITY','ACCESSIBILITY_SURFACE','EXISTING_ACCESSIBILITY_SURFACE','PLAY_ACCESSIBILITY_CREDITS',
  'plain-list accessible presentation','screen-reader semantic controls','Instant Text option','high-contrast option',
  '200% zoom requirement','same reducer across CRT / overlay / plain-list accessible mode',
  'I COULD USE A HINT.','A SMALL NUDGE.','BE MORE SPECIFIC.','JUST POINT ME AT THE NEXT STEP.'
 ]
 for p,t in active:
  for token in forbidden:
   if token in t: fail(f'forbidden active token {token!r} in {p.relative_to(root)}')
 ending=(root/'FULL_TEXT/06_UNIVERSAL_ENDING_CANON_FULL.md').read_text()
 for token in ['CASE_FILE_02_SEALED_TEASER=PRINCIPAL_APPROVED_INTENTIONAL_STATIC_STINGER','CASE FILE 02...................... SEALED','FUTURE ACCESS..................... PENDING']:
  if token not in ending: fail(f'missing Principal teaser token {token}')
 if 'MISSION_02_PLAYABLE_STATE=NONE' not in (root/'MAIN_INTEGRATION/04_STATE_MACHINE_AND_REDUCER_CONTRACT.md').read_text(): fail('missing no-playable-M02 state')
 templates=set()
 for p,t in active: templates.update(re.findall(r'\{\{[^}]+\}\}',t))
 if templates!=ALLOWED_TEMPLATES: fail(f'template set mismatch {templates}')
 state=json.loads((root/'STATE/final_story_state.json').read_text())
 checks={
  'a1_1_to_a1_5_full_text':True,'a1_haystack_canon':True,'a1_hieroglyphs_analogy':False,
  'dedicated_accessibility_options':False,'alternate_player_presentation':False,
  'mission_02_playable':False,'mission_02_work_scope':False,'runtime_provider_calls':0,'main_handoff_ready':True}
 for k,v in checks.items():
  if state.get(k)!=v: fail(f'state {k} expected {v!r}, got {state.get(k)!r}')
 if state.get('mission_02_teaser')!='PRINCIPAL_APPROVED_INTENTIONAL_STATIC_STINGER': fail('teaser status')
 if (root/'NANSEN_API_KEY.txt').exists(): fail('credential included')
 return {'a1_sha256':EXPECTED_A1,'templates':sorted(templates)}

